with care_matrix (organization_id, care_setting, first_ordinal, profile_count) as (
  values
    ('00000000-0000-4000-8000-000000000101'::varchar, 'Outpatient Clinic'::varchar, 1, 15),
    ('00000000-0000-4000-8000-000000000101', 'Medical Ward', 16, 8),
    ('00000000-0000-4000-8000-000000000101', 'Surgical Ward', 24, 7),
    ('00000000-0000-4000-8000-000000000101', 'O&G Ward', 31, 4),
    ('00000000-0000-4000-8000-000000000102', 'Outpatient Clinic', 35, 15),
    ('00000000-0000-4000-8000-000000000102', 'Medical Ward', 50, 9),
    ('00000000-0000-4000-8000-000000000102', 'Surgical Ward', 59, 5),
    ('00000000-0000-4000-8000-000000000102', 'O&G Ward', 64, 4),
    ('00000000-0000-4000-8000-000000000103', 'Outpatient Clinic', 68, 15),
    ('00000000-0000-4000-8000-000000000103', 'Medical Ward', 83, 8),
    ('00000000-0000-4000-8000-000000000103', 'Surgical Ward', 91, 6),
    ('00000000-0000-4000-8000-000000000103', 'O&G Ward', 97, 4)
), generated as (
  select organization_id, care_setting, ordinal,
    lower(substr(md5('sentinel-patient-' || ordinal::text), 1, 8) || '-' || substr(md5('sentinel-patient-' || ordinal::text), 9, 4) || '-' || substr(md5('sentinel-patient-' || ordinal::text), 13, 4) || '-' || substr(md5('sentinel-patient-' || ordinal::text), 17, 4) || '-' || substr(md5('sentinel-patient-' || ordinal::text), 21, 12)) as id
  from care_matrix cross join lateral generate_series(first_ordinal, first_ordinal + profile_count - 1) as ordinal
)
insert into public.patients (id, reference, organization_id, care_setting, age_group, symptomatic, pregnancy_related, body_mass_index, documented_complexity, created_at)
select id, 'SYN-DM-' || lpad(ordinal::text, 3, '0'), organization_id, care_setting,
  case when ordinal % 3 = 0 then '18-44' when ordinal % 3 = 1 then '45-64' else '65+' end,
  ordinal % 17 = 0, care_setting = 'O&G Ward' and ordinal in (31, 64, 97),
  case when ordinal in (11, 22, 44) then 33.0 else 24.0 + (ordinal % 7) end,
  ordinal % 11 = 0, '2026-10-31T08:00:00Z'
from generated
on conflict (id) do nothing;

with indexed as (
  select id as patient_id, substring(reference from 8)::integer as ordinal from public.patients where reference like 'SYN-DM-%'
), rows as (
  select patient_id, ordinal, sequence, code, value, unit, days_ago, original_code, standard_code, coding_display, clinical_key, terminology_status, normalised_value, normalised_ucum_unit, method, egfr_equation
  from indexed cross join lateral (
    values
      (1, 'hba1c'::varchar, case when ordinal % 11 = 0 or ordinal in (1, 17, 45) then 6.0 else 5.8 end, '%'::varchar, 50, 'HBA1C'::varchar, '4548-4'::varchar, 'Hemoglobin A1c/Hemoglobin.total in Blood'::varchar, 'hba1c_ngsp'::varchar, 'verified'::varchar, case when ordinal % 11 = 0 or ordinal in (1, 17, 45) then 6.0 else 5.8 end, '%'::varchar, null::varchar, null::varchar),
      (2, 'fpg', case when ordinal % 11 = 0 or ordinal in (1, 17, 45) then 6.1 else 5.4 end, case when ordinal = 7 then 'mg/dL' else 'mmol/L' end, 48, 'FPG', '14749-6', 'Glucose [Moles/volume] in Serum or Plasma', case when ordinal = 7 then null else 'fpg' end, case when ordinal = 7 then 'unit_incompatible' else 'verified' end, case when ordinal = 7 then null else case when ordinal % 11 = 0 or ordinal in (1, 17, 45) then 6.1 else 5.4 end end, case when ordinal = 7 then null else 'mmol/L' end, null, null),
      (3, 'hba1c', case when ordinal % 11 = 0 or ordinal in (1, 17, 45) then 7.1 else 6.0 end, '%', 12, 'HBA1C', '4548-4', 'Hemoglobin A1c/Hemoglobin.total in Blood', 'hba1c_ngsp', 'verified', case when ordinal % 11 = 0 or ordinal in (1, 17, 45) then 7.1 else 6.0 end, '%', null, null),
      (4, 'fpg', case when ordinal % 11 = 0 or ordinal in (1, 17, 45) then 7.6 else 5.8 end, case when ordinal = 7 then 'mg/dL' else 'mmol/L' end, 10, 'FPG', '14749-6', 'Glucose [Moles/volume] in Serum or Plasma', case when ordinal = 7 then null else 'fpg' end, case when ordinal = 7 then 'unit_incompatible' else 'verified' end, case when ordinal = 7 then null else case when ordinal % 11 = 0 or ordinal in (1, 17, 45) then 7.6 else 5.8 end end, case when ordinal = 7 then null else 'mmol/L' end, null, null),
      (5, 'egfr', 72.0 - (ordinal % 9), 'mL/min/{1.73_m2}', 8, 'EGFR_CKD_EPI', '62238-1', 'Glomerular filtration rate [Volume Rate/Area] in Serum, Plasma or Blood by Creatinine-based formula (CKD-EPI)/1.73 sq M', 'egfr_ckd_epi', 'verified', 72.0 - (ordinal % 9), 'mL/min/{1.73_m2}', 'CKD-EPI creatinine-based formula / 1.73 sq M', 'CKD-EPI')
  ) as item(sequence, code, value, unit, days_ago, original_code, standard_code, coding_display, clinical_key, terminology_status, normalised_value, normalised_ucum_unit, method, egfr_equation)
  where not (ordinal = 9 and sequence = 5)
)
insert into public.observations (id, patient_id, code, value, unit, observed_at, ingested_at, source_id, version, is_corrected, is_late_arrival, original_code, coding_system, standard_code, coding_display, terminology_version, terminology_status, clinical_key, ucum_unit, normalised_value, normalised_ucum_unit, result_status, method, egfr_equation, provenance)
select lower(substr(md5('sentinel-observation-' || ordinal::text || '-' || sequence::text), 1, 8) || '-' || substr(md5('sentinel-observation-' || ordinal::text || '-' || sequence::text), 9, 4) || '-' || substr(md5('sentinel-observation-' || ordinal::text || '-' || sequence::text), 13, 4) || '-' || substr(md5('sentinel-observation-' || ordinal::text || '-' || sequence::text), 17, 4) || '-' || substr(md5('sentinel-observation-' || ordinal::text || '-' || sequence::text), 21, 12)),
  patient_id, code, value, unit, '2026-10-31T08:00:00Z'::timestamptz - (days_ago || ' days')::interval, '2026-10-31T08:00:00Z'::timestamptz - (greatest(days_ago - 1, 0) || ' days')::interval,
  'SRC-' || lpad(ordinal::text, 3, '0') || '-' || sequence::text, 1, false, ordinal = 13 and sequence = 1, original_code, 'http://loinc.org', standard_code, coding_display, '2.83', terminology_status, clinical_key, unit, normalised_value, normalised_ucum_unit, 'final', method, egfr_equation,
  jsonb_build_object('source', 'deterministic Supabase synthetic seed', 'synthetic_only', true)
from rows
on conflict (source_id, version) do nothing;

insert into public.conditions (id, patient_id, source_id, version, clinical_status, verification_status, source_coding_system, source_code, source_display, snomed_code, snomed_display, terminology_status, recorded_at, provenance)
select lower(substr(md5('sentinel-condition-' || id), 1, 8) || '-' || substr(md5('sentinel-condition-' || id), 9, 4) || '-' || substr(md5('sentinel-condition-' || id), 13, 4) || '-' || substr(md5('sentinel-condition-' || id), 17, 4) || '-' || substr(md5('sentinel-condition-' || id), 21, 12)),
  id, 'COND-' || lpad(substring(reference from 8), 3, '0'), 1, 'active', 'confirmed', 'http://snomed.info/sct', '44054006', 'Diabetes mellitus type 2 (disorder)', '44054006', 'Diabetes mellitus type 2 (disorder)', 'verified', '2026-10-31T08:00:00Z', jsonb_build_object('source', 'deterministic Supabase synthetic seed', 'synthetic_only', true)
from public.patients where reference like 'SYN-DM-%'
on conflict (source_id, version) do nothing;

insert into public.audit_events (id, actor_id, event_type, entity_type, entity_id, detail)
values ('00000000-0000-4000-8000-000000000401', '00000000-0000-4000-8000-000000000201', 'seed.completed', 'synthetic_dataset', 'sentinel-100', jsonb_build_object('patients', 100, 'care_mix', jsonb_build_object('outpatient', 45, 'medical', 25, 'surgical', 18, 'og', 12), 'synthetic_only', true))
on conflict (id) do nothing;
